{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, the highest-transfer analogue, has an absolute oral bioavailability of 60 ± 23% in healthy subjects in the fed state, directly supporting F ≥ 20% under the query's fed condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Trazodone showed an absolute oral bioavailability of 63% in fasted volunteers, with other records reporting 70–90%, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Eltrombopag had an estimated bioavailability of at least 52% after oral dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "DPP-4 inhibitors are well absorbed in humans with oral bioavailability of 75–87%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Urapidil has an absolute oral bioavailability of 78% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ondansetron has an absolute oral bioavailability of 75% in an older female group, with other records reporting ~60%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Metolazone is available in an approximately 100% bioavailable form, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Brexanolone has poor oral bioavailability (<5%), a contradictory low-F example, but this is outweighed by the consistent high-F evidence from multiple high-transfer analogues and the query's favorable physicochemical prior.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small neutral pyrazolone (antipyrine) with favorable physicochemical properties for absorption. Multiple high-transfer analogues with direct oral bioavailability measurements consistently show F ≥ 50%, including a fed-state measurement for ziprasidone. The few low or variable examples are either weak/inferential or outweighed by the preponderance of high-F evidence, so F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule is included in the provided evidence.",
    "Most supporting analogues were studied in fasted or unspecified conditions; only ziprasidone provides a direct fed-state absolute bioavailability measurement.",
    "Solubility/dissolution and first-pass metabolism for the query are inferred from physicochemical properties rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

